mapper.select:
SELECT sp.student_id AS id,sp.student_id AS studentId,sp.name,sp.age,sp.parent_phone AS parentPhone, sp.memo,sp.focus_areas AS focusAreas,sp.learner_type AS learnerType, c.name AS centerName, CASE sp.status WHEN 'ACTIVE' THEN '진행중' WHEN 'PAUSED' THEN '예정' ELSE '완료' END AS status, sp.sessions_limit AS sessionsTotal, COUNT(DISTINCT ts.session_id) AS sessionsScheduled, COUNT(DISTINCT CASE WHEN ts.status='COMPLETED' THEN ts.session_id END) AS sessionsDone, ROUND(AVG(pa.score),0) AS score, DATE_FORMAT(MAX(ts.scheduled_at),'%Y-%m-%d') AS lastSession FROM teacher_students relation JOIN student_profiles sp ON sp.student_id=relation.student_id JOIN centers c ON c.center_id=sp.center_id LEFT JOIN therapy_sessions ts ON ts.student_id=sp.student_id LEFT JOIN practice_attempts pa ON pa.student_id=sp.student_id WHERE relation.teacher_id=#{teacherId} AND relation.status='ACTIVE' AND (sp.name LIKE CONCAT('%',#{keyword},'%') OR sp.parent_phone LIKE CONCAT('%',#{keyword},'%'))
AND ((#{status}='진행중' AND sp.status='ACTIVE') OR (#{status}='예정' AND sp.status='PAUSED') OR (#{status}='완료' AND sp.status='COMPLETED') OR (#{status}=sp.status))
GROUP BY sp.student_id,sp.name,sp.age,sp.parent_phone,sp.memo,sp.focus_areas,sp.status,sp.learner_type,sp.sessions_limit,c.name ORDER BY sp.name LIMIT #{limit} OFFSET #{offset}

SELECT session_id AS sessionId,title,DATE_FORMAT(scheduled_at,'%Y-%m-%d') AS date,
  status,(status='COMPLETED') AS done,summary
FROM therapy_sessions WHERE student_id=#{studentId} ORDER BY scheduled_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT h.homework_id AS homeworkId,h.homework_id AS id,h.student_id AS studentId,sp.name AS studentName,
  h.title,h.type,h.description,h.target_minutes AS targetMinutes,DATE_FORMAT(h.due_date,'%Y-%m-%d') AS dueDate,
  h.status,(h.status='COMPLETED') AS done,h.exercise_id AS exerciseId,(SELECT ex.title FROM exercises ex WHERE ex.exercise_id=h.exercise_id) AS exerciseTitle,h.version,DATE_FORMAT(h.created_at,'%Y-%m-%dT%H:%i:%s') AS createdAt
FROM homeworks h JOIN student_profiles sp ON sp.student_id=h.student_id
WHERE h.teacher_id=#{teacherId}
AND h.student_id=#{studentId}
AND h.status=#{status}
ORDER BY h.due_date,h.homework_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM homeworks WHERE teacher_id=#{teacherId}
AND student_id=#{studentId}
AND status=#{status}

SELECT homework_id AS homeworkId,student_id AS studentId,title,type,description,target_minutes AS targetMinutes,
  due_date AS dueDate,status,(status='COMPLETED') AS done,version,exercise_id AS exerciseId FROM homeworks
WHERE teacher_id=#{teacherId} AND homework_id=#{homeworkId}

mapper.update:
UPDATE homeworks SET
title=#{title}, type=#{type}, description=#{description}, target_minutes=#{targetMinutes}, due_date=#{dueDate}, status=#{status}, status=CASE WHEN #{done}=TRUE THEN 'COMPLETED' ELSE 'PENDING' END, version=version+1,
WHERE teacher_id=#{teacherId} AND homework_id=#{homeworkId}
AND version=#{version}

