SELECT 
FROM speech_analyses sa JOIN exercises e ON e.exercise_id=sa.exercise_id
WHERE sa.student_id=#{studentId} AND sa.status IN ('COMPLETED','FAILED')
AND sa.review_status=#{reviewStatus}
ORDER BY sa.created_at DESC,sa.analysis_id LIMIT #{limit} OFFSET #{offset}
